import {useEffect,useState} from 'react';import {Plus} from 'lucide-react';import api,{message} from '../services/api.js';import Modal from '../components/Modal.jsx';
export default function Reservations(){const [rows,setRows]=useState([]),[books,setBooks]=useState([]),[members,setMembers]=useState([]),[open,setOpen]=useState(false),[form,setForm]=useState({bookId:'',memberId:'',notes:''}),[error,setError]=useState('');async function load(){try{setRows((await api.get('/reservations')).data)}catch(e){setError(message(e))}}async function opts(){try{const [b,m]=await Promise.all([api.get('/books'),api.get('/members')]);setBooks(b.data);setMembers(m.data)}catch(e){setError(message(e))}}useEffect(()=>{load();opts()},[]);async function save(e){e.preventDefault();try{await api.post('/reservations',form);setOpen(false);load()}catch(e){setError(message(e))}}async function change(id,status){try{await api.put(`/reservations/${id}`,{status});load()}catch(e){setError(message(e))}}return <><div className="page-head"><div><h2>Reservations</h2><p>Manage requests for unavailable or popular books.</p></div><button className="btn primary" onClick={()=>{setError('');setOpen(true)}}><Plus size={17}/>New reservation</button></div>{error&&<div className="alert error">{error}</div>}<div className="panel table-wrap"><table><thead><tr><th>Book</th><th>Member</th><th>Requested</th><th>Status</th><th>Action</th></tr></thead><tbody>{rows.map(r=><tr key={r._id}><td><b>{r.book?.title}</b><small>{r.book?.author}</small></td><td>{r.member?.name}<small>{r.member?.memberId}</small></td><td>{new Date(r.createdAt).toLocaleDateString()}</td><td><span className={`badge ${r.status==='approved'?'success':r.status==='rejected'?'danger':'neutral'}`}>{r.status}</span></td><td>{r.status==='pending'&&<div className="inline-actions"><button className="btn small" onClick={()=>change(r._id,'approved')}>Approve</button><button className="btn small danger" onClick={()=>change(r._id,'rejected')}>Reject</button></div>}</td></tr>)}{!rows.length&&<tr><td colSpan="5" className="empty">No reservations.</td></tr>}</tbody></table></div><Modal open={open} onClose={()=>setOpen(false)} title="Create reservation"><form onSubmit={save} className="form-grid"><label className="full-col">Book<select required value={form.bookId} onChange={e=>setForm({...form,bookId:e.target.value})}><option value="">Select book</option>{books.map(b=><option key={b._id} value={b._id}>{b.title}</option>)}</select></label><label className="full-col">Member<select required value={form.memberId} onChange={e=>setForm({...form,memberId:e.target.value})}><option value="">Select member</option>{members.map(m=><option key={m._id} value={m._id}>{m.memberId} — {m.name}</option>)}</select></label><label className="full-col">Notes<textarea rows="3" value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></label><div className="modal-actions"><button type="button" className="btn" onClick={()=>setOpen(false)}>Cancel</button><button className="btn primary">Create</button></div></form></Modal></>}
